// TestEphemeralWrite_CapturesTheWorktreeThatHoldsTheFiles is the RED test for the
// cwd prerequisite (spec §2). buildTreeWithChanges resolves paths.WorktreeRoot
// ITSELF (checkpoint/ephemeral.go:791) rather than receiving turn-end's repoRoot,
// so converting only turn-end's local — the "narrow" half-fix — leaves the store
// reading the wrong worktree.
//
// The failure is NOT a deletion. Measured on origin/main:
//   - shared.go, which exists in BOTH worktrees, is captured with the MAIN
//     checkout's unmodified bytes. The checkpoint claims the file as touched
//     while recording that the agent changed nothing. Plausible-looking, wrong.
//   - wtonly.go, which exists only in the linked worktree, is silently ABSENT:
//     fileExists() fails, ephemeral.go:818-822 records a nil entry ("treat as
//     deletion"), and deleting a path that is not in the base tree is a no-op.
//
// The nil-entry/deletion branch only produces a visible deletion for a path that
// is in the base tree but missing from the resolved worktree's disk — a much
// narrower case than either of the above. A test asserting "no nil entries"
// therefore PASSES on the broken behaviour; assert content and presence instead.
func TestEphemeralWrite_CapturesTheWorktreeThatHoldsTheFiles(t *testing.T) {
	t.Run("control_cwd_in_worktree", func(t *testing.T) {
		mainDir, wtDir, metadataDir, base := setupWorktreeScenario(t)
		tree := writeEphemeralFromCwd(t, mainDir, metadataDir, base, wtDir)

		got, ok := fileContentInTree(t, tree, "shared.go")
		if !ok {
			t.Fatal("shared.go absent from shadow tree")
		}
		if got != agentEdit {
			t.Errorf("shared.go = %q, want the agent's edit %q", got, agentEdit)
		}
		if got, ok := fileContentInTree(t, tree, "wtonly.go"); !ok {
			t.Error("wtonly.go absent from shadow tree; the agent created it")
		} else if got != agentNew {
			t.Errorf("wtonly.go = %q, want %q", got, agentNew)
		}
	})

	// RED until the ephemeral store resolves the worktree from the turn's event
	// rather than from process cwd.
	t.Run("cwd_in_main_checkout", func(t *testing.T) {
		mainDir, _, metadataDir, base := setupWorktreeScenario(t)
		tree := writeEphemeralFromCwd(t, mainDir, metadataDir, base, mainDir)

		got, ok := fileContentInTree(t, tree, "shared.go")
		if !ok {
			t.Fatal("shared.go absent from shadow tree")
		}
		if got == baseContent {
			t.Errorf("shared.go captured the MAIN checkout's bytes %q: the checkpoint "+
				"claims the file as touched while recording that the agent changed nothing", got)
		}
		if got != agentEdit {
			t.Errorf("shared.go = %q, want the agent's edit %q", got, agentEdit)
		}
		if _, ok := fileContentInTree(t, tree, "wtonly.go"); !ok {
			t.Error("wtonly.go silently absent from shadow tree: fileExists() failed against " +
				"the wrong worktree, and the nil-entry 'deletion' is a no-op for a path not in the base tree")
		}
	})
}

